properties.query:
// Only events ingested since the last run (see tools/build.py)
let CowrieNew = Cowrie_CL | where ingestion_time() > ago(1h);
CowrieNew
| where eventid =~ "cowrie.command.input" and input matches regex "(^|[;&|]\\s*)((ba)?sh\\s+\\S+|\\./\\S+|/(tmp|var/tmp|var/run|dev/shm)/\\S+).*[;&|]\\s*rm\\s"
